export type V1RouteId = keyof typeof v1Routes;

export type V1Route = (typeof v1Routes)[V1RouteId];

export const buildV1Path = (
  routeId: V1RouteId,
  params: Record<string, string | number> = {},
): string =>
  v1Routes[routeId].path.replace(/\{([^}]+)\}/g, (_match, key: string) => {
    const value = params[key];

    if (value === undefined) {
      throw new Error(`Missing route parameter ${key} for ${routeId}`);
    }

    return encodeURIComponent(String(value));
  });
